import{_ as r,o,c as a,ao as i}from"./chunks/framework.cyfFUN0r.js";const y=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),t={name:"privacy.md"};function n(s,e,c,l,d,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h1><p>Effective date: 2026-09-16</p><p>This policy covers the Open Grind app, made by Open Grind Governance. Contact: <a href="mailto:admin@opengrind.org" target="_blank" rel="noreferrer">admin@opengrind.org</a></p><h2 id="where-your-data-goes" tabindex="-1">Where your data goes <a class="header-anchor" href="#where-your-data-goes" aria-label="Permalink to “Where your data goes”">​</a></h2><p>The app contacts each service below only for the features you use, over encrypted connections. Each service receives your IP address.</p><ul><li><strong>Grindr</strong>: your sign-in details, profile, photos, messages, location, reports and everything else you do on Grindr through the app, plus random device identifiers the app creates. See <a href="https://www.grindr.com/privacy-policy" target="_blank" rel="noreferrer">Grindr&#39;s Privacy Policy</a>.</li><li><strong>Google</strong>, if you sign in with Google: what you enter on Google&#39;s sign-in page. See <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google&#39;s Privacy Policy</a>.</li><li><strong>Meta</strong>, if you sign in with Facebook: what you enter on Facebook&#39;s sign-in page. See <a href="https://www.facebook.com/privacy/policy/" target="_blank" rel="noreferrer">Meta&#39;s Privacy Policy</a>.</li><li><strong>OpenStreetMap</strong>, when the app shows a map for picking your location: requests for the map tiles of the area shown. See the <a href="https://osmfoundation.org/wiki/Privacy_Policy" target="_blank" rel="noreferrer">OpenStreetMap Foundation&#39;s Privacy Policy</a>.</li><li><strong>git.opengrind.org</strong>, if you check for updates, allow automatic update checks, or install or update an add-on: requests for release lists and files, with no account details or device identifiers. The file names can show your operating system and processor type.</li></ul><h2 id="on-your-device" tabindex="-1">On your device <a class="header-anchor" href="#on-your-device" aria-label="Permalink to “On your device”">​</a></h2><p>The app keeps your session, device identifiers, settings and saved location on your device. It keeps the session and device identifiers in your system&#39;s credential storage where one is available. Signing out deletes your session and saved location and replaces the device identifiers with new ones. Uninstalling the app on Android deletes all of it.</p><h2 id="our-servers" tabindex="-1">Our servers <a class="header-anchor" href="#our-servers" aria-label="Permalink to “Our servers”">​</a></h2><p>Open Grind Governance runs opengrind.org and git.opengrind.org on servers in Germany. They receive your IP address and the page or file you request, and use them only to send it to you. The legal basis is our legitimate interest in delivering what you request (GDPR Art. 6(1)(f)). The servers keep no access logs and store no IP addresses.</p><p>You have the right to access, correct or delete your personal data and to restrict its processing. You have the right to object to this processing at any time. You can also complain to a data protection authority.</p>',11)])])}const g=r(t,[["render",n]]);export{y as __pageData,g as default};
